void shell_sort(int a[], int n) {
    for (int gap = n / 2; gap > 0; gap /= 2) {
        for (int i = gap; i < n; i++) {
            int tmp = a[i];
            int j = i;
            while (j >= gap && a[j - gap] > tmp) {
                a[j] = a[j - gap];     /* shift by gap, not by 1 */
                j -= gap;
            }
            a[j] = tmp;
        }
    }
}

void shell_sort_knuth(int a[], int n) {
    int h = 1;
    while (h < n / 3) h = 3 * h + 1;      /* 1, 4, 13, 40, 121, ... */
    for (; h >= 1; h /= 3) {
        for (int i = h; i < n; i++) {
            int tmp = a[i], j = i;
            while (j >= h && a[j - h] > tmp) {
                a[j] = a[j - h];
                j -= h;
            }
            a[j] = tmp;
        }
    }
}

static const int ciura[] = {701, 301, 132, 57, 23, 10, 4, 1};

void shell_sort_ciura(int a[], int n) {
    for (int g = 0; g < 8; g++) {
        int h = ciura[g];
        if (h >= n) continue;             /* skip gaps larger than the array */
        for (int i = h; i < n; i++) {
            int tmp = a[i], j = i;
            for (; j >= h && a[j - h] > tmp; j -= h)
                a[j] = a[j - h];
            a[j] = tmp;
        }
    }
}
